function table(headers:string[],rows:string[][],label:string){return `<div class="table-wrap" tabindex="0" role="region" aria-label="${label}"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>i?`<td>${x}</td>`:`<th scope="row">${x}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
export function motivationHtml(lang:Language){
 const pageWord=t('Печатные / PDF страницы','Páginas impresas / PDF','Printed / PDF pages','Gedrukte / PDF-pagina’s')[lang];
 const h=(s:string)=>`<h2>${s}</h2>`;
 let html=`<blockquote><p>${status[lang]}</p></blockquote>${h(t('Как работать с главой','Cómo estudiar el tema','How to study this chapter','Dit hoofdstuk bestuderen')[lang])}<p>${goals[lang]}</p>`;
 for(const b of allBlocks){
 html+=h(b.title[lang])+`<p class="ref"><a href="${source}#page=${b.pages.split('–')[0]}">${pageWord}: ${b.pages}</a></p>`+b.paragraphs.map(p=>`<p>${p[lang]}</p>`).join('');
 if(b.id==='history')html+=table([t('Период','Periodo','Period','Periode')[lang],t('Акцент','Énfasis','Emphasis','Nadruk')[lang]],timeline.map(([a,b])=>[a,b[lang]]),b.title[lang]);
 if(b.id==='method')html+=`<figure class="mot-diagram"><figcaption>${t('Четыре фазы метода','Cuatro fases del método','Four method phases','Vier methodefasen')[lang]}</figcaption><ol>${phases.map(([a,b],i)=>`<li><strong>${i+1}. ${b[lang]}</strong><br/><span lang="es">${a}</span></li>`).join('')}</ol></figure>`;
 if(b.id==='approaches')html+=table([t('Подход','Enfoque','Approach','Benadering')[lang],t('Фокус','Foco','Focus','Nadruk')[lang]],approaches.map((a,i)=>[`<a href="#${a.id}">${a.title[lang]}</a>`,[t('Обучение и последствия','Aprendizaje y consecuencias','Learning and consequences','Leren en gevolgen'),t('Обработка информации','Procesamiento de información','Information processing','Informatieverwerking'),t('Телесные механизмы','Mecanismos corporales','Bodily mechanisms','Lichaamsmechanismen'),t('Бессознательные конфликты','Conflictos inconscientes','Unconscious conflicts','Onbewuste conflicten'),t('Опыт и рост','Experiencia y crecimiento','Experience and growth','Ervaring en groei'),t('Адаптивные истоки','Orígenes adaptativos','Adaptive origins','Adaptieve oorsprong'),t('Культура и взаимодействия','Cultura e interacción','Culture and interaction','Cultuur en interactie')][i][lang]]),b.title[lang]);
 if(b.id==='processes')html+=`<figure class="mot-diagram"><figcaption>${t('Восемь процессов и их функции','Ocho procesos y sus funciones','Eight processes and their functions','Acht processen en hun functies')[lang]}</figcaption>${[0,1].map(g=>`<section><h3 lang="es">${g?'Cognitivos o superiores':'Activadores'}</h3><ul>${processes.slice(g?2:0,g?8:2).map(([a,b])=>`<li><strong lang="es">${a}</strong> — ${b[lang]}</li>`).join('')}</ul></section>`).join('')}</figure>`;
 html+=`<p><strong>${exampleLabel[lang]}.</strong> ${b.example[lang]}</p><p class="mot-question"><strong>${questionLabel[lang]}.</strong> ${b.question[lang]}</p><details><summary>${answerLabel[lang]}</summary><p>${b.answer[lang]}</p></details>`;
 }
 html+=h(t('Что знать к экзамену','Qué saber para el examen','What to know for the exam','Wat je voor het examen moet kennen')[lang])+`<ul>${allBlocks.map(b=>`<li><a href="#${b.id}">${b.title[lang]}</a>: ${b.question[lang]}</li>`).join('')}</ul><p>${t('Без подсказки назовите два блока целей науки, четыре цели психологии, три нормы, четыре фазы, семь подходов и восемь процессов с их функциями. Объясните ограничения выводов.','Enumera sin ayuda dos bloques de objetivos científicos, cuatro metas psicológicas, tres normas, cuatro fases, siete enfoques y ocho procesos con sus funciones. Explica los límites de las conclusiones.','Recall two scientific goal pairs, four psychological goals, three standards, four phases, seven approaches and eight processes with their functions. Explain the limits of conclusions.','Noem twee wetenschappelijke doelparen, vier psychologische doelen, drie normen, vier fasen, zeven benaderingen en acht processen met hun functies. Verklaar de grenzen van conclusies.')[lang]} <a href="#self-check">${t('К восьми вопросам','A las ocho preguntas','Go to the eight questions','Naar de acht vragen')[lang]}</a></p>`;
 html+=h(t('Глоссарий UNED','Glosario UNED','UNED glossary','UNED-begrippenlijst')[lang])+`<dl>${[...glossary,...processes.map(([a,b])=>[a,b] as [string,Text])].map(([a,b])=>`<dt lang="es"><strong>${a}</strong></dt><dd>${b[lang]}</dd>`).join('')}</dl>`;
 html+=h(t('Карта 76 mínimos','Mapa de los 76 mínimos','Map of the 76 mínimos','Kaart van de 76 mínimos')[lang])+`<p><a href="${minimums}">Conocimientos mínimos · Tema 1 (2026)</a>. ${t('Номер → раздел с объяснением и заданием. Проверьте, можете ли вы ответить своими словами.','Número → apartado con explicación y aplicación. Comprueba si puedes responder con tus palabras.','Number → section with explanation and application. Check whether you can answer in your own words.','Nummer → onderdeel met uitleg en toepassing. Controleer of je in eigen woorden kunt antwoorden.')[lang]}</p>`+table(['Mínimo',t('Раздел / задание','Apartado / aplicación','Section / application','Onderdeel / toepassing')[lang],pageWord],motivationCoverage.map(c=>[String(c.number),`<a href="#${c.section}">${allBlocks.find(b=>b.id===c.section)!.title[lang]}</a>`,c.pages]),'76 mínimos');
 html+=h(t('Источники','Fuentes','Sources','Bronnen')[lang])+`<p>${status[lang]}</p><ol><li>Menéndez Balaña, F. J. «Introducción al Estudio de la Psicología». <em>Manual de Psicología de la Motivación</em>, ${pageWord} 3–16. <a href="${source}">${t('Проверенный скан главы','Capítulo escaneado consultado','Reviewed chapter scan','Geraadpleegde hoofdstukscan')[lang]}</a>.</li><li><a href="${minimums}">Conocimientos mínimos · Tema 1 (2026)</a>: 76.</li><li>Menéndez Balaña, F. J.; Rivero Expósito, M. P.; Sanz Aparicio, M. T.; Toril Barrera, M. P. (coord.). <em>Manual de Psicología de la Motivación</em>. Madrid: Sanz y Torres, 1.ª ed., 2026. ISBN 978-84-10409-69-9. <a href="${publisher}">${t('Издательство','Editorial','Publisher','Uitgever')[lang]}</a>; <a href="${uned}">UNED · 62011089 · 2026/2027</a>.</li></ol><p>${t('Выходные данные сверены с каталогом и программой; скан не содержит издательской страницы. Номера страниц относятся к этому скану: печатная и PDF-нумерация совпадают. Dorsch и исторические работы цитируются по главе, а не как отдельно проверенные первоисточники.','Los datos editoriales se verificaron en catálogo y guía; el escaneo no incluye página editorial. Las páginas corresponden a este escaneo: numeración impresa y PDF coincidente. Dorsch y obras históricas se citan a través del capítulo, no como fuentes primarias consultadas por separado.','Publication details were checked in catalogue and course guide; the scan has no publication-details page. Page numbers refer to this scan, where printed and PDF numbering agree. Dorsch and historical works are cited through the chapter, not as separately reviewed primary sources.','Publicatiegegevens zijn gecontroleerd in catalogus en studiegids; de scan heeft geen uitgeverspagina. Paginanummers gelden voor deze scan, met gelijke gedrukte en PDF-nummers. Dorsch en historische werken zijn via het hoofdstuk aangehaald, niet als afzonderlijk geraadpleegde primaire bronnen.')[lang]}</p>`;
 return html;
}
const quizRows:[Text,Text,Text,Text,Text][]=[
[t('Что изучает научная психология?','¿Qué estudia la psicología científica?','What does scientific psychology study?','Wat bestudeert wetenschappelijke psychologie?'),t('Поведение и психические процессы с учётом внутренних условий и среды','Conducta y procesos mentales considerando condiciones internas y entorno','Behaviour and mental processes in relation to internal conditions and environment','Gedrag en mentale processen in relatie tot interne omstandigheden en omgeving'),t('Только поведение','Solo conducta','Only behaviour','Alleen gedrag'),t('Только мысли человека вне среды','Solo pensamientos humanos sin entorno','Only human thoughts without environment','Alleen menselijke gedachten zonder omgeving'),t('Первый ответ объединяет предмет. «Только поведение» исключает внутренние процессы; «только мысли» исключает действия, других животных и среду.','La primera integra el objeto. Solo conducta excluye procesos internos; solo pensamientos excluye acciones, otros animales y entorno.','The first integrates the subject. Behaviour alone excludes mental processes; thoughts alone exclude action, other animals and environment.','Het eerste antwoord verbindt het onderwerp. Alleen gedrag sluit mentale processen uit; alleen gedachten sluiten handelen, andere dieren en omgeving uit.')],
[t('Чем наука отличается от житейской психологии?','¿Qué distingue ciencia y sentido común?','What distinguishes science from common-sense psychology?','Wat onderscheidt wetenschap van alledaagse psychologie?'),t('Систематическим методом и независимой проверкой','Método sistemático y contrastación independiente','Systematic method and independent checking','Systematische methode en onafhankelijke toetsing'),t('Интуиция всегда ложна','La intuición siempre es falsa','Intuition is always false','Intuïtie is altijd onjuist'),t('Согласием большинства','Acuerdo de la mayoría','Majority agreement','Instemming van de meerderheid'),t('Различие в методе. Житейское объяснение может быть верно, а большинство — ошибаться; ни один из этих вариантов не заменяет проверки.','La diferencia es metodológica. Una explicación cotidiana puede acertar y la mayoría equivocarse; ninguna sustituye contrastación.','The difference is method. Everyday explanations can be right and majorities wrong; neither replaces checking.','Het verschil zit in de methode. Alledaagse verklaringen kunnen kloppen en meerderheden dwalen; geen van beide vervangt toetsing.')],
[t('Каковы четыре фазы метода?','¿Cuáles son las cuatro fases del método?','What are the four method phases?','Wat zijn de vier methodefasen?'),t('Наблюдение → гипотеза → предсказание и эксперимент → проверка результатов','Observación → hipótesis → deducción y experimentación → contrastación','Observation → hypothesis → prediction and experimentation → checking results','Observatie → hypothese → voorspelling en experiment → resultaten toetsen'),t('Догадка → уверенность','Conjetura → certeza','Guess → certainty','Gissing → zekerheid'),t('Шесть обязательных фаз вместо четырёх','Seis fases obligatorias en vez de cuatro','Six required phases instead of four','Zes verplichte fasen in plaats van vier'),t('Четыре фазы включают проверку. Уверенность не заменяет данных; шесть шагов примера лишь разворачивают четыре фазы, а не меняют их перечень.','Las cuatro fases incluyen contrastación. La certeza no sustituye datos; los seis pasos del ejemplo desarrollan las cuatro fases, no las reemplazan.','Four phases include testing. Certainty does not replace evidence; the six example steps expand the four phases rather than replace them.','Vier fasen omvatten toetsing. Zekerheid vervangt geen gegevens; de zes voorbeeldstappen werken vier fasen uit en vervangen ze niet.')],
[t('Как различаются индукция и дедукция?','¿Cómo se distinguen inducción y deducción?','How do induction and deduction differ?','Hoe verschillen inductie en deductie?'),t('Индукция обобщает наблюдения; дедукция выводит предсказание из гипотезы','Inducción generaliza observaciones; deducción deriva predicciones de una hipótesis','Induction generalises observations; deduction derives predictions from a hypothesis','Inductie generaliseert observaties; deductie leidt voorspellingen uit een hypothese af'),t('Обе — только сбор чисел','Ambas son solo recoger números','Both only collect numbers','Beide verzamelen alleen cijfers'),t('Индукция окончательно доказывает любой закон','Inducción prueba definitivamente cualquier ley','Induction definitively proves any law','Inductie bewijst elke wet definitief'),t('Различается направление рассуждения. Данные не равны операции вывода, а обобщение остаётся ограниченным и проверяемым, не окончательным доказательством.','Difiere la dirección del razonamiento. Los datos no son una inferencia; generalizar sigue siendo limitado y contrastable, no una prueba definitiva.','The direction of inference differs. Data are not an inference, and generalisation remains limited and testable rather than definitive proof.','De redeneerrichting verschilt. Gegevens zijn geen gevolgtrekking en generalisaties blijven begrensd en toetsbaar, geen definitief bewijs.')],
[t('На чём сосредоточен когнитивный подход?','¿En qué se centra el enfoque cognitivo?','What does the cognitive approach focus on?','Waarop richt de cognitieve benadering zich?'),t('Приобретение, обработка, хранение и использование информации','Adquisición, procesamiento, almacenamiento y uso de información','Acquiring, processing, storing and using information','Informatie verwerven, verwerken, opslaan en gebruiken'),t('Только гормоны','Solo hormonas','Only hormones','Alleen hormonen'),t('Только бессознательные конфликты','Solo conflictos inconscientes','Only unconscious conflicts','Alleen onbewuste conflicten'),t('Информация — когнитивный фокус. Гормоны относятся к биологическому уровню, бессознательный конфликт — к психодинамическому; уровни могут дополняться.','La información es el foco cognitivo; hormonas, biológico; conflictos inconscientes, psicodinámico. Los niveles pueden complementarse.','Information is the cognitive focus; hormones are biological; unconscious conflicts psychodynamic. The levels can complement one another.','Informatie is de cognitieve nadruk; hormonen zijn biologisch, onbewuste conflicten psychodynamisch. Niveaus kunnen elkaar aanvullen.')],
[t('Как соотносятся фундаментальная и прикладная психология?','¿Cómo se relacionan básica y aplicada?','How do basic and applied psychology relate?','Hoe verhouden fundamentele en toegepaste psychologie zich?'),t('Взаимодополняются; прикладная также исследует эффективность','Se complementan; la aplicada también investiga eficacia','They complement each other; applied psychology also researches effectiveness','Ze vullen elkaar aan; toegepaste psychologie onderzoekt ook effectiviteit'),t('Прикладная не исследует','La aplicada no investiga','Applied psychology does no research','Toegepaste psychologie doet geen onderzoek'),t('Базовые знания бесполезны','Lo básico es inútil','Basic knowledge is useless','Fundamentele kennis is nutteloos'),t('Фундаментальные знания обосновывают помощь, прикладные исследования проверяют её. Практическая цель не отменяет исследования, а теория не отделена от применения.','Los conocimientos básicos fundamentan intervenciones y la investigación aplicada las evalúa. Una meta práctica no elimina investigación ni la teoría está aislada de aplicación.','Basic knowledge grounds intervention, and applied research evaluates it. A practical goal does not remove research, and theory is not isolated from application.','Fundamentele kennis onderbouwt interventies en toegepast onderzoek evalueert ze. Een praktisch doel sluit onderzoek niet uit en theorie staat niet los van toepassing.')],
[t('Какие процессы относятся к activadores?','¿Qué procesos son activadores?','Which processes are activadores?','Welke processen zijn activadores?'),t('Мотивация и эмоция','Motivación y emoción','Motivation and emotion','Motivatie en emotie'),t('Память и язык','Memoria y lenguaje','Memory and language','Geheugen en taal'),t('Внимание и восприятие','Atención y percepción','Attention and perception','Aandacht en waarneming'),t('Мотивация и эмоция — activadores. Память, язык, внимание и восприятие относятся к cognitivos/superiores; не путайте функцию активации с обработкой информации.','Motivación y emoción son activadores. Memoria, lenguaje, atención y percepción son cognitivos/superiores; activación no equivale a procesamiento de información.','Motivation and emotion are activators. Memory, language, attention and perception are cognitive/higher; activation is not information processing.','Motivatie en emotie zijn activatoren. Geheugen, taal, aandacht en waarneming zijn cognitief/hoger; activatie is niet informatieverwerking.')],
[t('Почему процессы изучают совместно?','¿Por qué estudiar los procesos conjuntamente?','Why study the processes together?','Waarom processen samen bestuderen?'),t('Разные функции взаимодействуют ради адаптации','Funciones distintas interactúan para adaptarse','Distinct functions interact in adaptation','Verschillende functies werken samen bij aanpassing'),t('Все процессы означают одно и то же','Todos significan lo mismo','They all mean the same thing','Ze betekenen allemaal hetzelfde'),t('Мотивация одна объясняет любую ошибку','La motivación explica por sí sola cualquier error','Motivation alone explains every error','Motivatie alleen verklaart elke fout'),t('Процессы различны, но связаны. Усталость может снизить внимание при сохранной цели; поэтому ни тождество процессов, ни единственная причина «мотивация» не подходят.','Son distintos pero relacionados. El cansancio puede reducir atención manteniendo la meta; no son idénticos ni basta atribuir todo a motivación.','Processes differ but connect. Fatigue can reduce attention while goals remain; processes are not identical and motivation is not the sole explanation.','Processen verschillen maar hangen samen. Vermoeidheid kan aandacht verminderen terwijl doelen blijven; processen zijn niet identiek en motivatie verklaart niet alles.')],
];
export function motivationQuestions(lang:Language):EducationalNewsQuizQuestion[]{return quizRows.map(([q,c,w1,w2,e],i)=>{const choices=[c,w1,w2];const order=i%2?[1,0,2]:[0,2,1];return {question:q[lang],choices:order.map(j=>choices[j][lang]),correctIndex:order.indexOf(0),explanation:e[lang]};});}
